// ============================================================
// FUNZIONI DI SUPPORTO (adattate dalla logica originale dell'app Snack)
// ============================================================

function searchAllMotu(query) {
  const q = (query || '').toLowerCase().trim();
  if (!q) return [];
  const results = [];
  Object.entries(CATALOG).forEach(([serie, subs]) => {
    Object.entries(subs).forEach(([sub, items]) => {
      items.forEach(item => {
        if (item.name.toLowerCase().includes(q)) {
          results.push({ ...item, serie, sub });
        }
      });
    });
  });
  return results;
}

// Genera la lista per la pagina Collection Value
function getValueRowsMotu(ownedIds, valueIds) {
  const rows = [];
  Object.entries(CATALOG).forEach(([serie, subs]) => {
    Object.entries(subs).forEach(([sub, items]) => {
      items.forEach(item => {
        if (!ownedIds[item.id]) return;
        const hasVariants = Array.isArray(item.variants) && item.variants.length > 0;
        if (hasVariants) {
          item.variants.forEach(v => {
            const looseKey = `v-loose-${v.id}`;
            const mocKey = `v-moc-${v.id}`;
            const looseOn = !!valueIds[looseKey];
            const mocOn = !!valueIds[mocKey];
            const total = (looseOn ? (v.priceLoose || 0) : 0) + (mocOn ? (v.priceMOC || 0) : 0);
            rows.push({
              key: v.id, name: item.name, year: item.year || '-', wave: item.wave || '-',
              variant: v.name, priceLoose: v.priceLoose || 0, priceMOC: v.priceMOC || 0,
              looseKey, mocKey, looseOn, mocOn, total, serie, sub,
            });
          });
        } else {
          const looseKey = `v-loose-${item.id}`;
          const mocKey = `v-moc-${item.id}`;
          const looseOn = !!valueIds[looseKey];
          const mocOn = !!valueIds[mocKey];
          const total = (looseOn ? (item.priceLoose || 0) : 0) + (mocOn ? (item.priceMOC || 0) : 0);
          rows.push({
            key: item.id, name: item.name, year: item.year || '-', wave: item.wave || '-',
            variant: '-', priceLoose: item.priceLoose || 0, priceMOC: item.priceMOC || 0,
            looseKey, mocKey, looseOn, mocOn, total, serie, sub,
          });
        }
      });
    });
  });
  return rows;
}

function getItemsMotu(serie, sub) {
  if (!serie) return [];
  const serieData = CATALOG[serie];
  if (!serieData) return [];
  if (sub) return serieData[sub] || [];
  return Object.values(serieData).flat();
}

function getStatsMotu(ownedIds, serie, sub) {
  if (!serie) {
    let total = 0, owned = 0;
    Object.values(CATALOG).forEach(serieData => {
      Object.values(serieData).forEach(items => {
        total += items.length;
        owned += items.filter(i => ownedIds[i.id]).length;
      });
    });
    return { total, owned, missing: total - owned, pct: total ? Math.round(owned / total * 100) : 0 };
  }
  const items = getItemsMotu(serie, sub);
  const owned = items.filter(i => ownedIds[i.id]).length;
  return { total: items.length, owned, missing: items.length - owned, pct: items.length ? Math.round(owned / items.length * 100) : 0 };
}

